/**
 * Kill switch for working without signal (specs/offline-mode, NFR-5).
 *
 * On unless `public/runtime-config.js` (generated by the deploy) says
 * `offlineMode: false`; then the service worker unregisters itself and the read
 * cache and outbox stay off. Reads `window.EMAUS_RUNTIME_CONFIG` directly instead
 * of going through `config/runtimeConfig.ts`, which many tests mock with only
 * `getApiUrl`.
 */
export const isOfflineModeEnabled = (): boolean => {
	try {
		return typeof window === 'undefined' || window.EMAUS_RUNTIME_CONFIG?.offlineMode !== false;
	} catch {
		return true;
	}
};
